INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$home.about$c$, 'cs', $c$O společnosti UA GREEN$c$, $c$<p><img src="/media/6a464f2d1a6d4a7ea85d2420.jpg"></p><p>Jsme hrdí na náš tým, který navrhuje a vyrábí špičkové vertikální větrné elektrárny.</p><p>UA GREEN je přední výrobce větrných elektráren, známý po celé Ukrajině vynikající kvalitou, výjimečným zákaznickým servisem a konkurenceschopnými cenami. Jsme profesionální energetická společnost s výhodnou polohou v samém srdci Lvova.</p><p>Společnost UA GREEN už více než dva roky rozvíjí svou značku a stala se partnerem předních firem, jako je ROZETKA.</p><p><a href="https://uagreen.co">Číst dále</a></p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$home.projects$c$, 'cs', $c$Úplná energetická nezávislost$c$, $c$<p>Klienti se na nás obracejí pro ucelená energetická řešení na klíč pro své domácnosti, domy, firmy i kanceláře.</p><p><img src="/media/66a31a9394e0ee54cbf9b482.jpg"></p><h3>Domácnost</h3><p>Při výpadcích elektřiny je důležité, aby vaše domácnost fungovala bez přerušení. Nabízíme komplexní řešení pro váš komfort.</p><ul><li>Větrná elektrárna 1 kW;</li><li>Hybridní střídač 4,2 kW;</li><li>Baterie na 6 hodin záložního napájení;</li><li>Instalace.</li></ul><p><img src="/media/66a31beb94e0ee54cbf9b5ce.jpg"></p><h3>Soukromý podnik</h3><p>Stabilní provoz vašeho podniku je klíčem k hospodářskému úspěchu celé země. Zajistíme vám spolehlivý zdroj energie 24/7, po celý rok!</p><ul><li>Větrně-solární elektrárna 15 kW;</li><li>3 hybridní střídače;</li><li>Baterie na 12 hodin záložního napájení;</li><li>Instalace.</li></ul><p><a href="/cs/about-us#projects">Další projekty</a></p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$home.faq$c$, 'cs', $c$Máte ještě otázky?$c$, $c$<p>Projděte si sekci níže nebo nás kontaktujte.</p><p>Máte-li jakékoli dotazy ohledně nákupu nebo vrácení peněz, naši specialisté vám vždy rádi pomohou. Kontaktujte nás ještě dnes, získejte potřebné odpovědi a začněte naplno využívat výhod obnovitelné energie.</p><h3>Pošlete nám svůj dotaz →</h3><h3>Jaké typy větrných elektráren nabízíte?</h3><p>Nabízíme široký sortiment řešení pro obnovitelnou energii, včetně větrných elektráren, střídačů, baterií, elektroniky, montážního materiálu, instalačních služeb a mnoha dalšího.</p><h3>Jak dlouho trvá doručení objednávky?</h3><p>Doba doručení závisí na objednaném produktu a místě doručení. Předobjednávky doručujeme zpravidla do 2 až 4 týdnů, u rozměrných komponentů vyráběných na zakázku však může výroba a doručení trvat 3 až 6 měsíců.</p><h3>Jak mohu vrátit zboží?</h3><p>Pokud nejste s nákupem spokojeni, můžete zboží do 14 dnů vrátit a získat zpět celou částku. Více informací vám poskytne náš zákaznický servis.</p><h3>Nabízíte nějaké speciální slevy?</h3><p>Ano, během roku nabízíme řadu slev a speciálních nabídek. Navštivte náš web nebo se přihlaste k odběru newsletteru, abyste měli přehled o aktuálních akcích.</p><h3>Poskytujete na vybavení záruku?</h3><p>Ano, na veškeré vybavení zakoupené v našem obchodě poskytujeme záruku jeden rok.</p><h3>Online platba</h3><p>Vybavení snadno objednáte tak, že vybrané produkty vložíte do košíku a bezpečně je zaplatíte přímo na našem webu.</p><h3>Zákaznická podpora</h3><p>Pokud si výběrem nejste jisti, naši specialisté vám rádi poradí po telefonu na čísle +380957173772.</p><h3>Doprava po městě zdarma</h3><p>Užijte si bezplatné a včasné doručení kamkoli ve městě. Bez minimální hodnoty objednávky!</p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$home.hero$c$, 'cs', $c$UA GREEN Větrné elektrárny a vybavení k nim$c$, $c$<p>Staňte se energeticky nezávislými: pořiďte si naši sestavu vybavení!</p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$home.passion$c$, 'cs', $c$Vášeň pro ekologické inovace$c$, $c$<p>Čtěte články o energetické účinnosti, trendech v obnovitelné energetice a udržitelnosti.</p><p><img src="/media/66a2fc0e94e0ee54cbf99f41.jpg"></p><h2>Účinnost</h2><p>Naši zkušení specialisté zavádějí inovace do komponentů větrných turbín a posouvají hranice účinnosti a výkonu.</p><p><img src="/media/66a175b9138461b805e70f51.jpg"></p><h2>Energie</h2><p>Našim zákazníkům můžeme zaručit, že všechny naše větrné turbíny jsou optimalizovány pro maximální energetickou účinnost a šetrnost k životnímu prostředí.</p><p><img src="/media/66a136ce96cece80b7c5fa4d.jpg"></p><h2>Ekologie</h2><p>Hnací silou našeho podnikání jsou inovativní konstrukce větrných turbín. Naším cílem je zaujmout zákazníky tím, jak vážně bereme ochranu životního prostředí.</p><p><a href="https://uagreen.co">Požádat o zavolání</a></p><p>Jste začínající technik, nebo talentovaný konstruktér? Rádi s vámi probereme možnost spolupráce!</p><h3>Kontaktujte nás →</h3>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$home.services$c$, 'cs', $c$Výhody$c$, $c$<p>Naše vybavení je dostupné po celém světě a nabízí tyto výhody:</p><h3>Popis</h3><p>Poskytujeme podrobné popisy produktů.</p><h3>Široký výběr</h3><p>Široký sortiment vybavení.</p><h3>Bez minimální objednávky</h3><p>Žádná minimální hodnota objednávky.</p><h3>Pravidelné aktualizace</h3><p>Naše produkty pravidelně aktualizujeme.</p><h3>Snadné objednání</h3><p>Kontaktujte naše manažery a objednávku vyřídíte rychle.</p><h3>Po celém světě</h3><p>Doručení po celém světě, včetně expresní přepravy.</p><h3>Zákaznická podpora</h3><p>Zákaznická podpora 24/7.</p><h3>Skladem</h3><p>Produkty skladem připravené k odeslání.</p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$page.404$c$, 'cs', $c$Jejda! Vypadá to, že nás solární panely nechaly na holičkách.$c$, $c$<p><img src="/media/66b34ae421d898ad1ab5cd17.png"></p><p>Stránku, kterou hledáte, nelze najít, protože ji napájely solární panely – a teď je noc.</p><p><a href="/cs/shop/cat/vitroelektrostanciyi">Nezkusíme to raději se spolehlivými větrnými elektrárnami?</a></p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$page.about$c$, 'cs', $c$O nás$c$, $c$<h2>Naše výroba</h2><p>Naše výroba větrných elektráren nemá obdoby! Vybavení vyrábíme z vysoce kvalitních materiálů, takže každý výrobek vydrží dlouhá léta.</p><p>Na svou řemeslnou zručnost a smysl pro detail jsme náležitě hrdí. Naše větrné elektrárny jsou navrženy tak, aby váš domov zásobovaly čistou a spolehlivou energií. Každá sestava je postavena podle nejvyšších standardů kvality, díky nimž je skutečně výjimečná.</p><p>Naše větrné elektrárny se hodí do nejrůznějších lokalit, od venkovských domů po městské bydlení. Dokážou napájet cokoli od malého rodinného domu až po velkou vilu.</p><p>Náš tým zkušených specialistů věnuje každé větrné elektrárně maximální péči, aby zajistil její dlouhou životnost a vysokou účinnost. Nabízíme širokou škálu modelů, od klasických po moderní, takže si jistě vyberete řešení, které odpovídá vašim potřebám.</p><p>Ať už hledáte novou větrnou elektrárnu pro svůj dům, nebo potřebujete řešení na míru, náš tým pro výrobu větrných elektráren je vám k dispozici.</p><p><img src="/media/66a175f1c2c64781790f65b5.jpg"></p><p>Ve společnosti UA GREEN využíváme moderní technologie a postupy, abychom zajistili nejvyšší kvalitu našich větrných elektráren. Tradiční výrobní techniky kombinujeme s pokročilými procesy, a vytváříme tak spolehlivé a účinné systémy.</p><p>Naše větrné elektrárny vyrábíme kombinací automatizovaných strojů a zručné ruční práce.</p><p>Komponenty našich větrných elektráren řežeme, tvarujeme a sestavujeme na moderních CNC strojích a finální úpravy pak dokončujeme ručně. K tvorbě 3D modelů našich systémů používáme také pokročilý software pro počítačově podporované projektování (CAD).</p><p>Díky tomu dokážeme větrné elektrárny vyrábět rychle a přesně. Na své výrobky jsme hrdí a používáme pouze vysoce kvalitní materiály. Pro bezpečnost našich systémů používáme také ekologicky šetrná lepidla a povrchové úpravy.</p><p><img src="/media/66a3436304b4e4154071bfd9.jpg"></p><h2>Historie naší energetické společnosti</h2><p>Naše firma urazila dlouhou cestu a stále roste.</p><p><strong>Listopad 2022 — Útok na ukrajinskou energetickou infrastrukturu přiměl skupinu stejně smýšlejících lidí hledat alternativní zdroje elektřiny.</strong></p><p><strong>Prosinec 2022 — Naši konstruktéři vyvinuli první prototypy větrné elektrárny.</strong></p><p><strong>Duben 2023</strong> — Zahájili jsme výrobu a ladění naší první vertikální větrné elektrárny K400 a proběhly první testy funkčního prototypu větrné elektrárny K1000 V1.</p><h3>Srpen 2023 — Založení společnosti UA GREEN LLC a prodej naší první větrné elektrárny!</h3><p><strong>Leden 2024 — Účast v celoukrajinském podnikatelském akcelerátoru „Vlasne“ a postup do finále!</strong></p><h3>Březen 2024 — Zahájení hromadného prodeje našich větrných elektráren.</h3><p><strong>Červenec 2024 — Kvůli složité situaci v Charkově, který je neustále pod ruskými útoky, jsme se rozhodli přesunout výrobu do Lvova.</strong></p><h3>Sláva Ukrajině! Hrdinům sláva!</h3><h2>Showroom UA GREEN</h2><p>Náš showroom je ideálním místem, kde najdete správnou sestavu vybavení pro svou firmu, domov či kancelář.</p><p>Nabízíme široký výběr větrných elektráren, včetně modelů 1 kW a 5 kW, a také střídače, regulátory a mnoho dalšího. Náš zkušený a znalý tým vám pomůže sestavit jedinečný komplet vybavení přesně podle vašich potřeb a rozpočtu.</p><h3>Kde nás najdete</h3><p><em>ul. Volynska 10, Lvov</em></p><p><em>+38 (095) 717 37 72 | oc.neergau%40okneratyt.anaitet</em></p><h3><em>Otevírací doba:</em></h3><h3><em>Pondělí – sobota: 11:00–19:00</em></h3><h3><em>Neděle: 11:00–19:00</em></h3><p><img src="/media/6788446e5c0c7a0c0ed4151b.jpg"></p><h2>Vybavení na klíč</h2><p>Klienti se na nás obracejí pro kompletní řešení na klíč pro své výrobní provozy, domy a kanceláře.</p><p><img src="/media/66a8207bbd57757b7d11f232.jpg"></p><h3>Záložní napájecí systém</h3><p>Naši klienti často volí záložní napájecí systém, který při výpadcích sítě udrží v chodu nezbytná zařízení. Takový systém zajistí až 12 hodin autonomního provozu a později jej lze rozšířit o větrnou elektrárnu nebo solární panely.</p><ul><li>Hybridní střídač 4,2 kW 24V;</li><li>Baterie LiFePO4 100 Ah 24V (~2,4 kWh);</li><li>Montážní materiál a kabely;</li></ul><p><img src="/media/678844973318debec79c18bc.jpg"></p><h3>Větrná elektrárna pro rodinný dům</h3><p>Vlastní větrná elektrárna bude vyrábět elektřinu 24/7. Spolu se střídačem a bateriemi může být tato sestava skvělým prvním krokem k úplné energetické nezávislosti.</p><ul><li>Větrná elektrárna 1 kW 24V</li><li>Hybridní střídač 4,2 kW 24V</li><li>Baterie LiFePO4 100 Ah 24V (~2,4 kWh);</li><li>Stožár 10 m</li></ul><p><img src="/media/66a822d4bd57757b7d11f484.jpg"></p><h3>Větrně-solární elektrárna</h3><p>Větrně-solární elektrárna vám zajistí energii v každém ročním období a za každého počasí. Jeden alternativní zdroj vyrovnává omezení druhého, takže váš domov zůstane energeticky odolný i při úplném blackoutu.</p><ul><li>Větrná elektrárna 5 kW 48V</li><li>Solární panely 5 kW</li><li>Hybridní střídač 6,2 kW 48V</li><li>Baterie LiFePO4 200 Ah 48V (~10 kWh);</li><li>Stožár 10 m</li></ul>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$page.contacts$c$, 'cs', $c$Kontakty$c$, $c$<h2>Podmínky objednávky a doručení</h2><p>Před odesláním objednávky si prosím přečtěte tuto sekci.</p><p>OBCHODNÍ PODMÍNKY ZÁSADY OCHRANY OSOBNÍCH ÚDAJŮ ZÁKAZNICKÁ PODPORA ČASTO KLADENÉ DOTAZY</p><p>Snažíme se našim zákazníkům poskytovat co nejlepší služby a všechny objednávky vyřizovat co nejrychleji. Nákupem našeho vybavení online automaticky souhlasíte s následujícími podmínkami:</p><p><strong>01.</strong> Všechny objednávky zadané na tomto webu musí být uhrazeny v plné výši, než je odešle naše společnost nebo naši partneři.</p><p><strong>02.</strong> Veškeré zboží je nutné při převzetí zkontrolovat a jakékoli poškození neprodleně nahlásit prodávajícímu.</p><p><strong>03.</strong> Prodávající si vyhrazuje právo zrušit jakoukoli objednávku z důvodu problémů s platbou nebo jiných nepředvídaných okolností.</p><p><em>Máte-li jakékoli dotazy, obraťte se na naše specialisty. Stačí vyplnit kontaktní formulář a odeslat svůj dotaz. Naši zástupci vám odpoví co nejdříve. Kontaktovat nás můžete také jakýmkoli jiným způsobem, který vám vyhovuje.</em></p><h3>Jaké typy větrných elektráren nabízíte?</h3><p>Nabízíme široký sortiment vybavení, včetně vertikálních větrných elektráren o výkonu 1 kW a 5 kW, a mnoho dalšího.</p><h3>Jak dlouho trvá doručení objednávky?</h3><p>Doba doručení závisí na objednaném produktu a místě doručení. Objednávky doručujeme zpravidla do 2 až 3 týdnů. Dodání větrných elektráren o výkonu 5 kW může kvůli aktuálně vysoké poptávce trvat 3 až 5 měsíců.</p><h3>Jak mohu vrátit zboží?</h3><p>Pokud nejste s nákupem spokojeni, můžete zboží do 14 dnů vrátit a získat zpět celou částku. Více informací vám poskytne náš zákaznický servis.</p><h3>Nabízíte nějaké speciální slevy?</h3><p>Ano, během roku nabízíme řadu slev a speciálních nabídek. Navštivte náš web nebo se přihlaste k odběru newsletteru, abyste měli přehled o aktuálních akcích.</p><h3>Poskytujete na vybavení záruku?</h3><p>Ano, na veškeré vybavení zakoupené v našem obchodě poskytujeme záruku jeden rok.</p><h3>Jaké způsoby platby přijímáte?</h3><p>Přijímáme všechny hlavní platební karty (Visa, MasterCard) a také PayPal, Apple Pay a Google Pay.</p><h2>Způsoby platby a doručení</h2><h3>Platby</h3><ul><li>Online platba bankovní kartou (LiqPay). Zadejte objednávku a zaplaťte ji přímo na našem webu. Zvolíte-li platbu prostřednictvím faktury LiqPay, pošleme vám ji e-mailem, abyste mohli platbu dokončit</li><li>Bankovní převod. Zadejte objednávku a obdržíte fakturu, kterou lze uhradit jakoukoli bankovní kartou.</li><li>Nákup na úvěr. Pro fyzické osoby v rámci programu financování s 0% úrokem na nákup energetického vybavení. Program podporují tyto banky: PrivatBank, Oschadbank, Ukrgasbank, Sense Bank a Globus Bank. Maximální výše financování: až 480 000 UAH.</li></ul><h3>Doručení</h3><ul><li>Nova Poshta. Doručujeme po celé Ukrajině na nejbližší nákladovou pobočku Nova Poshta. Cena dopravy se vypočítá při objednávce a závisí na hmotnosti a rozměrech zásilky. Jakmile objednávku odešleme, pošleme vám oznámení s číslem expresního nákladního listu.</li><li>Ukrposhta. Doručujeme po celé Ukrajině na nejbližší pobočku Ukrposhta. Cena dopravy se vypočítá při objednávce a závisí na hmotnosti a rozměrech zásilky. Jakmile objednávka dorazí na pobočku, obdržíte oznámení SMS.</li><li>Osobní odběr v prodejně. Stačí zadat objednávku online a po jejím potvrzení si ji můžete osobně vyzvednout, kdy se vám to hodí. Jakmile bude objednávka připravena k vyzvednutí, dáme vám vědět.</li></ul><h2>Naše pobočky</h2><p>Navštivte náš showroom</p><p><img src="/media/642be1772ab297000d2b92fe.jpg"></p><h3>Hlavní kancelář, Charkov</h3><p><a href="tel:+380957173772">+38 (095) 717 37 72</a> | <a href="mailto:oc.neergau%40olleh">oc.neergau%40olleh</a></p><p>ul. Sadova 1, byt 117, Chroly, Charkovská oblast</p><p><img src="/media/642be1d623a10c000dc96067.jpg"></p><h3>Sklad, Lvov</h3><p><a href="tel:+380957173772">+38 (095) 717 37 72</a> | <a href="mailto:oc.neergau%40rukonyv.iiskelo">oc.neergau%40rukonyv.iiskelo</a></p><p>ul. Volynska 10, Lvov</p><p><img src="/media/66a3a0de58916475e2cfd55f.jpg"></p><h3>Showroom, Lvov</h3><p><a href="tel:+380668696072">+38 (066) 869 60 72</a> | oc.neergau%40okneratyt.anaitet</p><p>ul. Volynska 10, Lvov</p><h3>Záruční podmínky</h3><p>Na vybavení zakoupené v našem showroomu se vztahuje záruka až jeden rok od data nákupu. Záruka se nevztahuje na spotřební materiál, montážní materiál ani obaly.</p><ul><li>Pokud má vybavení zakoupené v našem showroomu výrobní vadu, bezplatně ho vyměníme.</li><li>Pokud se vybavení zakoupené v našem showroomu poškodí nehodou nebo běžným opotřebením, opravíme ho za příplatek.</li><li>Vyhrazujeme si právo odmítnout záruční servis nebo vrácení zboží, pokud se zjistí, že bylo poškozeno nesprávným používáním nebo z nedbalosti.</li></ul><h3>Podmínky vrácení zboží</h3><ul><li>Zboží lze vrátit do 14 dnů od nákupu. Veškeré vrácené zboží musí být v původním stavu, včetně všech originálních obalů a štítků.</li><li>Náklady na zpětnou přepravu nese zákazník, který rovněž odpovídá za bezpečné zabalení všech položek pro přepravu.</li><li>Vyhrazujeme si právo odmítnout jakékoli vrácení, které není v souladu s našimi podmínkami vrácení zboží. Náklady na dopravu se nevracejí.</li><li>Peníze vracíme stejným způsobem, jakým byla provedena platba. Zpracování vrácení peněz může trvat 5–7 pracovních dnů.</li></ul><p><em>Potřebujete-li záruční opravu nebo chcete-li vrátit zboží, kontaktujte naše manažery jakýmkoli způsobem, který vám vyhovuje. Uděláme vše pro to, abychom vám pomohli co nejrychleji. Pokud máte s objednávkou nebo platbou jakékoli potíže, neváhejte nás kontaktovat e-mailem nebo telefonicky. Náš zákaznický servis je k dispozici 24/7.</em></p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$page.oplata$c$, 'cs', $c$Platba a doručení$c$, $c$<p>Platba</p><ul><li>Online platba bankovní kartou (LiqPay). Zadejte objednávku a zaplaťte ji přímo na našem webu. Zvolíte-li platbu prostřednictvím faktury LiqPay, pošleme vám ji e-mailem, abyste mohli platbu dokončit.</li><li>Bankovní převod. Zadejte objednávku a obdržíte fakturu, kterou lze uhradit jakoukoli bankovní kartou.</li><li>Nákup na úvěr. Pro fyzické osoby v rámci programu financování s 0% úrokem na nákup energetického vybavení. Program podporují tyto banky: PrivatBank, Oschadbank, Ukrgasbank, Sense Bank a Globus Bank. Maximální výše financování: až 480 000 UAH.</li></ul><p>Doručení</p><ul><li>Nova Poshta. Doručujeme po celé Ukrajině na nejbližší nákladovou pobočku Nova Poshta. Cena dopravy se vypočítá při objednávce a závisí na hmotnosti a rozměrech zásilky. Jakmile objednávku odešleme, pošleme vám oznámení s číslem expresního nákladního listu.</li><li>Ukrposhta. Doručujeme po celé Ukrajině na nejbližší pobočku Ukrposhta. Cena dopravy se vypočítá při objednávce a závisí na hmotnosti a rozměrech zásilky. Jakmile objednávka dorazí na pobočku, obdržíte oznámení SMS.</li><li>Osobní odběr v prodejně. Stačí zadat objednávku online a po jejím potvrzení si ji můžete osobně vyzvednout, kdy se vám to hodí. Jakmile bude objednávka připravena k vyzvednutí, dáme vám vědět.</li></ul><h3>Nákup na splátky</h3><p><strong>V našem obchodě můžete využít splátky monobank. Objednávku zaplatíte ve stejných splátkách bez přeplatků a dalších poplatků. První splátku uhradíte při nákupu.</strong></p><h3>Splátky monobank | Universal Bank</h3><h3>Poskytovatel služby:</h3><p><strong>AS „UNIVERSAL BANK“, licence NBU č. 92 ze dne 20. ledna 1994, Státní registr bank č. 226.</strong></p><h3>Podmínky produktu:</h3><ul><li><strong>Minimální částka na splátky: 1 UAH</strong></li><li><strong>Maximální částka na splátky: 400 000 UAH</strong></li><li><strong>Efektivní roční úroková sazba: 0,000001 %</strong></li><li><strong>Doba splácení: 3–25 splátek</strong></li><li><strong>Způsob splácení: stejné měsíční splátky</strong></li><li><strong>První splátka se hradí při nákupu</strong></li><li><strong>Informace o hlavních podmínkách produktu a příslušná upozornění najdete na webu produktu: chast.monobank.ua</strong></li></ul>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$page.vacancies$c$, 'cs', $c$Práce, která baví, a profesionální tým$c$, $c$<p>Rozvíjíme ty nejlepší talenty! Náš tým je naším největším bohatstvím a hnací silou celé společnosti. Své zaměstnance neustále vzděláváme a podporujeme jejich profesní růst!</p><h2>Nenašli jste vhodnou pozici?<br>Stačí vyplnit formulář.</h2><p><a href="https://forms.gle/j5TyjMBZJs34u3bw5">Ucházet se o pozici</a></p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$page.offer$c$, 'cs', $c$Veřejná nabídka$c$, $c$<p><em>Návrh. Bude zkontrolován právníkem.</em></p>
<h2>Veřejná nabídka služby „Posouzení větrných podmínek na místě“</h2>
<p>UA Green LLC (dále jen „Zhotovitel“) nabízí jakékoli fyzické nebo právnické osobě (dále jen „Objednatel“) uzavření smlouvy o poskytnutí služeb za podmínek této nabídky.</p>
<h3>1. Předmět</h3>
<p>1.1. Zhotovitel poskytuje službu „Posouzení větrných podmínek na místě“: analýzu modelovaných údajů o větru pro souřadnice lokality, výjezd a průzkum na místě (terén, překážky, zdroje turbulence), referenční měření větru, posouzení příjezdových cest, nejbližšího bodu připojení k síti a vzdálenosti od obytné zástavby a výběr místa instalace a doporučeného typu a výšky turbíny.</p>
<p>1.2. Výsledkem je písemná zpráva s předběžnou prognózou roční výroby energie, doporučeními ohledně umístění a turbíny a seznamem zjištěných omezení.</p>
<h3>2. Přijetí nabídky</h3>
<p>2.1. Nabídka je přijata zaplacením služby na webu uagreen.co po zaškrtnutí políčka „Souhlasím s podmínkami veřejné nabídky“. Smlouva je uzavřena okamžikem zaplacení.</p>
<h3>3. Cena a platba</h3>
<p>3.1. Platí cena uvedená na webu v okamžiku zaplacení. Platba se provádí ve výši 100 % předem, online prostřednictvím LiqPay.</p>
<h3>4. Termíny</h3>
<p>4.1. Objednatel si na webu vybere termín výjezdu z dostupných termínů. Zhotovitel termín potvrdí telefonicky.</p>
<p>4.2. Pokud zvolený termín přestane být dostupný nebo Objednatel požádá o jeho změnu, dohodnou se Strany na novém termínu telefonicky.</p>
<p>4.3. Zpráva je zaslána elektronicky do 10 pracovních dnů po výjezdu.</p>
<h3>5. Povinnosti</h3>
<p>5.1. Objednatel v dohodnutý den umožní specialistovi přístup do lokality a poskytne přesné údaje o její poloze.</p>
<p>5.2. Zhotovitel poskytne službu v dohodnutém termínu a v rozsahu popsaném v článku 1.</p>
<h3>6. Vrácení peněz</h3>
<p>6.1. Před termínem výjezdu může Objednatel objednávku zrušit kontaktováním manažera Zhotovitele; celá částka mu bude vrácena na kartu, ze které platil.</p>
<p>6.2. Po výjezdu se peníze nevracejí, ledaže služba nebyla poskytnuta z viny Zhotovitele.</p>
<h3>7. Odpovědnost</h3>
<p>7.1. Zpráva je předběžným odhadem založeným na modelovaných údajích a krátkém měření na místě; skutečná výroba závisí na počasí a provozních podmínkách.</p>
<h3>8. Osobní údaje</h3>
<p>8.1. Zaplacením Objednatel souhlasí se zpracováním osobních údajů v souladu se <a href="/cs/polityka-konfidentsiynosti">Zásadami ochrany osobních údajů</a>.</p>
<h3>9. Ostatní ustanovení</h3>
<p>9.1. Záležitosti, které tato nabídka neupravuje, se řídí právními předpisy Ukrajiny. Spory se řeší jednáním, a nedojde-li k dohodě, soudní cestou.</p>
<p>PRODÁVAJÍCÍ (ZHOTOVITEL):</p><h3>UA Green LLC (ТОВ «ЮА Грін»)</h3><p>Kód EDRPOU 45033277</p><p>Adresa: ul. Sadova 1, byt 117, obec Chroly, Charkovská oblast, Ukrajina</p><p>E-mail: hello@uagreen.co</p><p>Telefon: +38 (095) 717 37 72</p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$page.privacy$c$, 'cs', $c$Zásady ochrany osobních údajů$c$, $c$<p><em>Návrh. Bude zkontrolován právníkem.</em></p>
<p>Tyto zásady vysvětlují, jak společnost UA Green LLC (dále jen „Společnost“) zpracovává osobní údaje návštěvníků webu uagreen.co v souladu se zákonem Ukrajiny „O ochraně osobních údajů“.</p>
<h3>1. Jaké údaje shromažďujeme</h3>
<p>Jméno, telefonní číslo, e-mailovou adresu, adresu lokality nebo doručovací adresu, text zpráv a komentářů, životopisy (u žádostí o zaměstnání) a technické údaje o návštěvě (cookies, IP adresa) pro účely analytiky.</p>
<h3>2. Proč</h3>
<p>Abychom vás mohli kontaktovat na základě vaší žádosti, vyřídit objednávku nebo službu (včetně posouzení lokality), vést evidenci zákazníků a objednávek, posuzovat žádosti o zaměstnání a zlepšovat web.</p>
<h3>3. S kým je sdílíme</h3>
<p>S platební službou LiqPay za účelem zpracování plateb; s dopravci za účelem doručení objednávek; s vlastním účetním systémem Společnosti. Osobní údaje neprodáváme třetím stranám.</p>
<h3>4. Jak dlouho je uchováváme</h3>
<p>Tak dlouho, jak to vyžaduje účel zpracování a právní předpisy (včetně účetních pravidel); poté jsou údaje vymazány nebo anonymizovány.</p>
<h3>5. Vaše práva</h3>
<p>Písemnou žádostí na adresu hello@uagreen.co se můžete dotázat, které vaše údaje zpracováváme, požádat o jejich opravu nebo výmaz, případně odvolat svůj souhlas. Můžete také podat stížnost u zmocněnce Nejvyšší rady Ukrajiny pro lidská práva.</p>
<h3>6. Souhlas</h3>
<p>Odesláním formuláře na webu nebo provedením platby vyjadřujete souhlas s těmito zásadami.</p>
<p>SPRÁVCE OSOBNÍCH ÚDAJŮ:</p><h3>UA Green LLC (ТОВ «ЮА Грін»)</h3><p>Kód EDRPOU 45033277</p><p>Adresa: ul. Sadova 1, byt 117, obec Chroly, Charkovská oblast, Ukrajina</p><p>E-mail: hello@uagreen.co</p><p>Telefon: +38 (095) 717 37 72</p>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
INSERT INTO content (key, lang, title, body_html, updated_at) VALUES ($c$page.terms$c$, 'cs', $c$Podmínky použití$c$, $c$<p><a href="/cs/umovi-vikoristannya-saytu#custom">1. </a>Pojmy používané v Ofertě</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-1">2. </a>Obecná ustanovení a předmět Smlouvy</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-3">3. </a>Postup při zadání Objednávky</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-5">4. </a>Cena a platební podmínky</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-6">5. </a>Postup při dodání Zboží</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-7">6. </a>Jakost Zboží a záruční závazky</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-8">7. </a>Podmínky vrácení Zboží a peněz</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-9">8. </a>Práva a povinnosti</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-10">9. </a>Odpovědnost Smluvních stran</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-11">10. </a>Podmínky důvěrnosti</p><p><a href="/cs/umovi-vikoristannya-saytu#custom-12">11. </a>Ostatní podmínky</p><p>Prodávající</p><h3>SMLOUVA VEŘEJNÉ OFERTY (OFERTA)</h3><p><strong>Společnost s ručením omezeným „UA Green“ (dále jen „Společnost“ nebo „Prodávající“), kód EDRPOU 45033277, řádně registrovaná jako právnická osoba v souladu s právními předpisy Ukrajiny, nabízí neurčitému okruhu osob (fyzickým osobám, právnickým osobám, fyzickým osobám podnikatelům atd.) (dále jen „Kupující“ nebo „Zákazník“), společně dále jen „Smluvní strany“ a jednotlivě „Smluvní strana“, uzavřít s Prodávajícím smlouvu o prodeji zboží na dálku prostřednictvím webových stránek https://uagreen.co/ (dále jen „Smlouva“) za podmínek stanovených v této Ofertě.</strong></p><p>1. POJMY POUŽÍVANÉ V TÉTO OFERTĚ</p><p><strong>„SPOLEČNOST“, „PRODÁVAJÍCÍ“ — Společnost s ručením omezeným „UA Green“, kód EDRPOU 45033277, sídlo: Charkovská oblast, obec Chroly, ulice Sadova 1, byt 117.</strong></p><p><strong>„KUPUJÍCÍ“, „ZÁKAZNÍK“ — jakákoli osoba (fyzická osoba, právnická osoba, fyzická osoba podnikatel atd.), která postupem stanoveným touto Smlouvou dobrovolně a v plném rozsahu přijala všechny její podmínky bez výjimky za účelem koupě Zboží nabízeného k prodeji na Webových stránkách.</strong></p><p><strong>„OBJEDNÁVKA“ — řádně vyplněná žádost podaná Kupujícím na Webových stránkách o koupi Zboží, které si Kupující vybral.</strong></p><p><strong>„WEBOVÉ STRÁNKY“ — webové stránky dostupné na internetu na adrese https://uagreen.co/, včetně všech jejich podstránek; vlastníkem a správcem Webových stránek je Prodávající.</strong></p><p><strong>„ZBOŽÍ“ — sortiment výrobků prezentovaný na Webových stránkách, u nichž je uveden název, popis, technické parametry, cena a další informace a které jsou k dispozici ke koupi.</strong></p><p><strong>„AKCEPTACE“ — úplný a bezvýhradný souhlas Kupujícího s nabídkou Prodávajícího uzavřít tuto Smlouvu za podmínek v ní stanovených. Přijetí podmínek této Smlouvy představuje bezvýhradný souhlas Kupujícího se všemi ustanoveními této Smlouvy a bezvýhradné převzetí povinností, které Kupujícímu z této Smlouvy vyplývají. Neznalost těchto povinností nezbavuje Kupujícího odpovědnosti za jejich nedodržení a/nebo nesprávné dodržení podmínek této Smlouvy. Akceptace nastává okamžikem, kdy Kupující vloží Zboží prezentované na Webových stránkách do virtuálního nákupního košíku a přistoupí k zadání Objednávky.</strong></p><p><strong>Pokud některý pojem použitý v této Ofertě nemá jednoznačný výklad, Smluvní strany jej chápou a vykládají podle jeho doslovného gramatického významu s přihlédnutím k ustanovením platných právních předpisů Ukrajiny, zavedené obchodní praxi a obsahu a předmětu této Smlouvy.</strong></p><p>2. OBECNÁ USTANOVENÍ A PŘEDMĚT SMLOUVY</p><p><strong>2.1. Na základě této Smlouvy se Prodávající zavazuje převést na Kupujícího vlastnické právo ke Zboží v souladu s Objednávkou Kupujícího a Kupující se zavazuje Zboží zaplatit a převzít za podmínek této Smlouvy.</strong></p><p><strong>2.2. Tato Smlouva upravuje nákup a prodej Zboží na Webových stránkách Prodávajícího.</strong></p><p><strong>2.3. Vyobrazení Zboží na Webových stránkách má pouze ilustrativní charakter. Zboží zakoupené Kupujícím se může vzhledem od vyobrazení na Webových stránkách lišit.</strong></p><p><strong>2.4. Vložení Zboží prezentovaného na Webových stránkách do virtuálního nákupního košíku a zadání Objednávky Kupujícím představuje bezvýhradnou akceptaci Oferty a souhlas se všemi podmínkami této Smlouvy.</strong></p><p><strong>2.5. Kupující je povinen se s podmínkami této Smlouvy seznámit sám. Prodávající není povinen Kupujícího o existenci této Smlouvy dodatečně ani jinak informovat, kromě jejího zveřejnění na Webových stránkách.</strong></p><p><strong>2.6. Tato Smlouva je veřejnou smlouvou, a proto jsou její podmínky v souladu s článkem 633 občanského zákoníku Ukrajiny stejné pro všechny kupující.</strong></p><p><strong>2.7. Společnost je oprávněna Ofertu kdykoli podle vlastního uvážení změnit a/nebo doplnit, a to bez předchozího oznámení takových změn či doplnění. Nové znění Smlouvy (Oferty) nabývá účinnosti okamžikem jeho zveřejnění na Webových stránkách, nestanoví-li nové znění Smlouvy jinak.</strong></p><p><strong>2.8. Uzavřením Smlouvy (tj. akceptací podmínek Oferty způsobem uvedeným v této Smlouvě) Kupující potvrzuje následující</strong></p><h3>a) Kupující se s podmínkami této Oferty plně seznámil a souhlasí s nimi;</h3><p><strong>b) Kupující uděluje Prodávajícímu svolení ke shromažďování, zpracování a předávání osobních údajů za podmínek stanovených v této Ofertě. Souhlas se zpracováním osobních údajů platí po celou dobu trvání této Smlouvy a po neomezenou dobu po jejím ukončení. Uzavřením této Smlouvy Kupující dále potvrzuje, že byl (bez jakéhokoli dalšího oznámení) informován o právech stanovených zákonem Ukrajiny „O ochraně osobních údajů“ a o účelech shromažďování údajů a že jeho osobní údaje jsou Prodávajícímu předávány za účelem plnění této Smlouvy, provádění vyúčtování a k dalším souvisejícím účelům. Kupující rovněž souhlasí s tím, že Prodávající je oprávněn zpřístupnit a předat osobní údaje Kupujícího třetím osobám bez jakéhokoli dalšího oznámení Kupujícímu, pokud zůstane účel zpracování osobních údajů nezměněn. Kupující si je vědom rozsahu svých práv jako subjektu osobních údajů podle zákona Ukrajiny „O ochraně osobních údajů“ a rozumí mu.</strong></p><p><strong>2.9. Smluvní strany se dohodly, že místem uzavření této Smlouvy o Ofertě je sídlo Společnosti.</strong></p><p>3. POSTUP PŘI ZADÁNÍ OBJEDNÁVKY</p><p><strong>3.1. Kupující zadává Objednávku Zboží na Webových stránkách samostatně a podle vlastního uvážení.</strong></p><p><strong>3.2. Po přijetí Objednávky ji Prodávající zpracuje a připraví Zboží k prodeji. Doba potřebná k vyřízení Objednávky závisí na tom, zda má Prodávající příslušné Zboží v okamžiku zadání Objednávky k dispozici.</strong></p><p><strong>3.3. Prodávající zpracuje a potvrdí Objednávku Kupujícího do 3 (tří) pracovních dnů ode dne jejího zadání. Pokud Kupující zadá Objednávku o víkendu nebo ve státní svátek, začíná lhůta pro zpracování a potvrzení běžet prvním pracovním dnem následujícím po tomto víkendu nebo státním svátku.</strong></p><p><strong>3.4. Má-li Kupující jakékoli dotazy ohledně vlastností nebo parametrů Zboží, je povinen se před zadáním Objednávky obrátit na Prodávajícího a získat od něj příslušné informace.</strong></p><p><strong>3.5. Při zadání Objednávky uvádí Kupující údaje nezbytné k jejímu vyřízení. Kupující uvede své příjmení, jméno, jméno po otci, telefonní číslo, e-mailovou adresu, doručovací údaje a další požadované informace. Prodávající neodpovídá za žádné následky vyplývající z nepravdivých informací nebo nesprávných údajů poskytnutých Kupujícím. Za veškeré nepříznivé následky spojené s uvedením nepřesných nebo neúplných informací potřebných k zadání a vyřízení Objednávky nese odpovědnost výhradně Kupující.</strong></p><p>4. CENA A PLATEBNÍ PODMÍNKY</p><p><strong>4.1. Cenu každého jednotlivého Zboží stanovuje Prodávající podle vlastního uvážení a uvádí ji na Webových stránkách u každého Zboží.</strong></p><p><strong>4.2. Cena Zboží a celková cena Objednávky jsou uvedeny v národní měně Ukrajiny — ukrajinské hřivně (UAH) — za jednotku Zboží.</strong></p><h3>4.3. Prodávající může cenu Zboží na Webových stránkách jednostranně změnit.</h3><p><strong>4.4. Kupující může Zboží zaplatit jedním z následujících způsobů:</strong></p><p><strong>4.4.1. Úhradou 100 % (sto procent) celkové ceny Zboží při zadání Objednávky na Webových stránkách prostřednictvím elektronických platebních systémů, které jsou na Webových stránkách k dispozici.</strong></p><p><strong>4.4.2. Úhradou celkové ceny Zboží v několika splátkách:</strong></p><p><strong>1) záloha ve výši 50 % (padesáti procent) ceny Zboží, kterou Kupující uhradí do 3 (tří) kalendářních dnů od vystavení příslušné zálohové faktury. Fakturu vystaví Prodávající poté, co potvrdí, že je schopen Objednávku zadanou Kupujícím vyřídit;</strong></p><p><strong>2) doplatek zbývajících 50 % (padesáti procent) ceny Zboží, který Kupující uhradí do 3 (tří) kalendářních dnů od vystavení příslušné konečné faktury. Konečnou fakturu vystaví Prodávající v okamžiku předání Zboží Kupujícímu.</strong></p><p><strong>4.5. Chce-li Kupující zvolit platbu ve splátkách podle bodu 4.4.2 této Oferty, musí při zadání Objednávky na Webových stránkách uvést odpovídající poznámku, v níž vyjádří svůj úmysl platit ve splátkách.</strong></p><p><strong>4.6. Cena dopravy Zboží objednaného Kupujícím se stanoví podle místa a způsobu dodání, které Kupující uvedl v příslušné Objednávce, a Smluvní strany ji dohodnou způsobem přijatelným pro obě strany.</strong></p><p><strong>4.7. V případě neúplné nebo opožděné platby za objednané Zboží ze strany Kupujícího, jakož i v případě technických potíží s platbou nebo jiných nepředvídaných okolností si Prodávající vyhrazuje právo Objednávku zrušit a/nebo pozastavit dodání Zboží a/nebo pozastavit a/nebo zcela ukončit plnění svých závazků, a to bez odpovědnosti za případné následky takového postupu. V takových případech Prodávající Kupujícího o těchto okolnostech informuje a navrhne možná opatření k jejich řešení tak, aby bylo možné Objednávku řádně zpracovat a přijmout k vyřízení.</strong></p><p>5. POSTUP PŘI DODÁNÍ ZBOŽÍ</p><p><strong>5.1. Kupující má právo zvolit jeden z následujících způsobů převzetí (dodání) Zboží tím, že při zadání Objednávky vybere příslušnou možnost dodání (buď pomocí funkce automatického výběru způsobu dodání, nebo uvedením preferovaného způsobu dodání v poznámce k Objednávce):</strong></p><p><strong>5.1.1. Na kterékoli pobočce společnosti Nova Poshta, kde lze převzít Zboží příslušných rozměrů a hmotnosti, podle platného ceníku dopravce;</strong></p><p><strong>5.1.2. Na kterékoli pobočce akciové společnosti Ukrposhta, kde lze převzít Zboží příslušných rozměrů a hmotnosti, podle platného ceníku dopravce;</strong></p><p><strong>5.1.3. Osobním odběrem Kupujícím na určeném výdejním místě, přičemž manažer Prodávajícího Kupujícího předem kontaktuje a dohodne s ním místo odběru;</strong></p><p><strong>5.1.4. Dodáním a/nebo instalací objednaného Zboží přímo Prodávajícím, pokud Prodávající takovou službu nabízí. Tato služba se poskytuje výhradně podle uvážení Prodávajícího a Kupující ji nemůže požadovat jako povinnou. V případě takového dodání a/nebo instalace se postup a podmínky dodání/instalace objednaného Zboží dohodnou mezi Kupujícím a Prodávajícím při zadání Objednávky nebo po jejím zadání.</strong></p><p><strong>5.2. Při převzetí Zboží je Kupující povinen v přítomnosti zástupce přepravní služby nebo zástupce Prodávajícího ověřit, zda Zboží odpovídá požadovaným kvalitativním a kvantitativním parametrům, včetně názvu Zboží, množství, kompletnosti a dalších relevantních parametrů. Zjistí-li Kupující v místě převzetí jakékoli vady, je povinen o tom Prodávajícího neprodleně informovat.</strong></p><p><strong>5.3. Termín dodání Zboží si Kupující a Prodávající dohodnou telefonicky nebo jiným způsobem přijatelným pro obě Smluvní strany</strong></p><p><strong>5.4. Vlastnické právo ke Zboží, jakož i veškerá rizika spojená s jeho ztrátou a/nebo poškozením, přechází z Prodávajícího na Kupujícího okamžikem předání Zboží Kupujícímu za předpokladu, že Kupující uhradil plnou cenu Zboží postupem a za podmínek stanovených touto Smlouvou.</strong></p><p><strong>5.5. Zboží se Kupujícímu dodává zabalené způsobem obvyklým pro daný druh Zboží, který je dostatečný k zajištění jeho ochrany za běžných podmínek skladování a přepravy.</strong></p><p>6. JAKOST ZBOŽÍ A ZÁRUČNÍ ZÁVAZKY</p><p><strong>6.1. Prodávající se zavazuje dodat Kupujícímu objednané Zboží v náležité jakosti, které je vhodné k určenému účelu použití.</strong></p><p><strong>6.2. Jakost Zboží musí odpovídat požadavkům, které pro příslušnou kategorii Zboží stanoví platné právní předpisy, nařízení a technické normy.</strong></p><p><strong>6.3. Prodávající poskytuje na Zboží záruční servis po dobu záruční lhůty 12 (dvanácti) kalendářních měsíců za předpokladu, že Kupující dodržuje veškerá pravidla a požadavky na provoz Zboží uvedené v Návodu k obsluze a v této Smlouvě. Záruka se nevztahuje na spotřební materiál, montážní prvky, obaly a podobné položky.</strong></p><p><strong>6.4. Záruční lhůta začíná běžet dnem dodání nebo předání objednaného Zboží Kupujícímu.</strong></p><p><strong>6.5. Záruční lhůtu uvedenou v bodě 6.3 této Smlouvy lze po vzájemné dohodě Smluvních stran a za doplatek ze strany Kupujícího prodloužit o další období. Celkovou délku a cenu záručního servisu, včetně případné prodloužené záruční lhůty objednané Kupujícím, mohou Smluvní strany sjednat v Objednávce nebo jiným způsobem přijatelným pro obě strany.</strong></p><p><strong>6.6. Záruka na Zboží zcela zaniká, bylo-li Zboží upraveno nebo opraveno bez souhlasu Prodávajícího. Za úpravu se považuje i použití Zboží mimo rozsah jeho určeného použití vymezený v Návodu k obsluze. Záruka se nevztahuje na poruchy nebo vady způsobené přirozenými vnějšími vlivy, nedostatečnou údržbou, přetížením nebo nesprávným provozem Zboží. Zboží rovněž nesmí být vystaveno teplotním, vlhkostním, elektromagnetickým vlivům, mechanické deformaci ani jiným vlivům, které se při provozu nepovažují za běžné nebo předpokládané. I v takových případech záruka zcela zaniká.</strong></p><p><strong>6.7. Zjistí-li se během záruční lhůty jakákoli porucha Zboží jako celku nebo vada kterékoli jeho součásti, zavazuje se Prodávající vyslat svého zástupce, který zjištěnou poruchu posoudí.</strong></p><p><strong>6.8. Lhůtu k odstranění vad v průběhu záručního servisu si Smluvní strany dohodnou zvlášť v každém jednotlivém případě způsobem přijatelným pro obě Smluvní strany.</strong></p><p><strong>6.9. Dojde-li k poškození Zboží v důsledku jednání nebo opomenutí Kupujícího, nevztahuje se na takové Zboží záruční servis, výměna, vrácení ani náhrada. Dojde-li k poškození Zboží v důsledku nepředvídaných povětrnostních podmínek nebo jiných okolností vyšší moci, nevztahuje se na Zboží rovněž záruční servis, výměna, vrácení ani náhrada.</strong></p><p><strong>6.10. Zjistí-li Kupující během záruční lhůty poškození zařízení, je povinen o tom Prodávajícího neprodleně informovat, nejpozději však do 14 (čtrnácti) kalendářních dnů ode dne zjištění poškození nebo poruchy. Na žádost Prodávajícího je Kupující povinen Zboží nebo jeho příslušnou část vrátit. Všechny části Zboží vyřazené z provozu se vracejí Prodávajícímu k další likvidaci. Neinformuje-li Kupující Prodávajícího ve lhůtě uvedené v tomto bodě, ztrácí právo na záruční servis.</strong></p><p><strong>6.11. Selže-li Zboží nebo kterákoli jeho část během záruční lhůty a jde-li podle této Smlouvy o záruční případ, Prodávající takové zařízení na vlastní náklady opraví a/nebo vymění.</strong></p><p>7. PODMÍNKY VRÁCENÍ ZBOŽÍ A PENĚZ</p><p><strong>7.1. Kupující má právo vrátit zakoupené Zboží Prodávajícímu do 14 (čtrnácti) kalendářních dnů ode dne koupě (převzetí Zboží Kupujícím).</strong></p><p><strong>7.2. Vracené Zboží musí být v původním stavu a kompletní, včetně všech štítků a obalu a veškeré průvodní dokumentace (záručního listu, návodu atd.). Nejsou-li podmínky uvedené v tomto bodě splněny, je Prodávající oprávněn vrácení Zboží odmítnout, aniž by za takové Zboží poskytl jakoukoli náhradu.</strong></p><p><strong>7.3. Náklady na poštovní přepravu (nebo jiný způsob přepravy) Zboží, iniciuje-li Kupující jeho vrácení Prodávajícímu, hradí Kupující na vlastní náklady. Prodávající tyto náklady nenahrazuje.</strong></p><p><strong>7.4. Iniciuje-li Kupující vrácení Zboží, odpovídá za kvalitu jeho zabalení během přepravy k Prodávajícímu. Dojde-li v důsledku nedostatečného zabalení k poškození Zboží nebo se Zboží stane nepoužitelným, je Prodávající oprávněn vrácení Zboží odmítnout, aniž by za takové Zboží poskytl jakoukoli náhradu.</strong></p><p><strong>7.5. Prodávající si vyhrazuje právo zamítnout jakoukoli žádost Kupujícího o vrácení Zboží, pokud takové vrácení neodpovídá podmínkám vrácení stanoveným Prodávajícím.</strong></p><p><strong>7.6. Existuje-li zákonný důvod, aby Prodávající vrátil Kupujícímu peníze, vrácení se provede stejným platebním způsobem, jaký byl použit při koupi Zboží, nebo jiným způsobem dohodnutým mezi Smluvními stranami. Lhůta pro vrácení peněz podle tohoto bodu činí nejvýše 7 (sedm) pracovních dnů.</strong></p><p><strong>7.6. Existuje-li zákonný důvod, aby Prodávající vrátil Kupujícímu peníze, je Kupující povinen sdělit Prodávajícímu písemně nebo jiným způsobem dohodnutým mezi Smluvními stranami údaje bankovního účtu, na který Prodávající peníze převede, bude-li reklamace Kupujícího oprávněná.</strong></p><p><strong>7.7. Vrací-li Prodávající Kupujícímu peníze v případech stanovených touto Smlouvou, bankovní poplatky a poplatky platebních systémů se Kupujícímu nevracejí.</strong></p><p><strong>7.8. Prodávající je dále oprávněn odmítnout převzetí vraceného Zboží v těchto případech:</strong></p><p><strong>7.8.1. Bylo-li Zboží použito, je-li narušen jeho obchodní vzhled, chybějí-li plomby nebo štítky, chybí-li obal nebo je poškozen, chybí-li průvodní dokumentace (Návod k obsluze, záruční list) atd.;</strong></p><p><strong>7.8.2. Objednal-li si Kupující Zboží, které bylo vyrobeno a/nebo dodáno speciálně pro Kupujícího na individuální objednávku a není součástí běžného sortimentu Prodávajícího.</strong></p><p><strong>7.9. Adresu, na kterou lze Zboží Prodávajícímu podle podmínek této Smlouvy vrátit, sdělí Prodávající Kupujícímu zvlášť v každém jednotlivém případě způsobem přijatelným pro Smluvní strany. Odešle-li Kupující vracené Zboží na jinou adresu, než kterou mu Prodávající sdělil, může to mít pro Kupujícího nepříznivé následky, včetně finančních, za které odpovídá výhradně Kupující.</strong></p><p>8. PRÁVA A POVINNOSTI</p><h3>8.1. Prodávající má právo:</h3><h3>8.1.1. Požadovat po Kupujícím dodržování podmínek této Smlouvy.</h3><p><strong>8.1.2. Pozastavit prodej a/nebo dodání Zboží, pokud Kupující řádně neplní své povinnosti.</strong></p><p><strong>8.1.3. Jednostranně měnit tuto Smlouvu a ceny Zboží zveřejněním příslušných změn na Webových stránkách. Takové změny nabývají účinnosti okamžitě po zveřejnění, nestanoví-li podmínky nové Oferty jinak.</strong></p><p><strong>8.1.4. Není-li Zboží objednané Kupujícím k dispozici, je Prodávající oprávněn takové Zboží z Objednávky odstranit a/nebo Objednávku Kupujícího zrušit, a to za předpokladu, že o tom Kupujícího předem informuje a zrušení s ním dohodne způsobem přijatelným pro Smluvní strany.</strong></p><p><strong>8.1.5. Zajišťovat doručení Objednávek prostřednictvím třetích osob poskytujících přepravní služby.</strong></p><p><strong>8.1.6. Vykonávat další práva, která prodávajícímu přiznává zákon Ukrajiny „O ochraně práv spotřebitelů“.</strong></p><h3>8.2. Prodávající je povinen:</h3><p><strong>8.2.1. Předat Kupujícímu Zboží za podmínek a postupem stanovenými touto Smlouvou.</strong></p><p><strong>8.2.2. Poskytnout ke Zboží potřebné dokumenty, včetně řádně vyplněného záručního listu u Zboží, na které se vztahuje záruční servis, a Návodu k obsluze Zboží.</strong></p><p><strong>8.2.3. Plnit další povinnosti, které prodávajícímu ukládá zákon Ukrajiny „O ochraně práv spotřebitelů“.</strong></p><h3>8.3. Kupující má právo:</h3><p><strong>8.3.1. Požadovat po Prodávajícím řádné plnění této Smlouvy v souladu s podmínkami v ní uvedenými.</strong></p><h3>8.3.2. Vybírat Zboží a zadávat Objednávky na příslušných stránkách Webových stránek.</h3><p><strong>8.3.3. Odmítnout převzetí vadného nebo nekompletního Zboží, případně Zboží, které neodpovídá zadané Objednávce, v souladu s podmínkami stanovenými v této Ofertě.</strong></p><p><strong>8.3.4. Odmítnout zasílání reklamních materiálů a dalších obchodních nabídek Prodávajícího, které mohou být zasílány na kontaktní údaje poskytnuté Kupujícím.</strong></p><p><strong>8.3.5. Vykonávat další práva, která kupujícímu přiznává zákon Ukrajiny „O ochraně práv spotřebitelů“.</strong></p><h3>8.4. Kupující je povinen:</h3><p><strong>8.4.1. Před zadáním Objednávky na Webových stránkách se pečlivě seznámit s informacemi o Zboží, jeho cenou a ostatními podmínkami této Smlouvy.</strong></p><p><strong>8.4.2. Řádně zaplatit a převzít zadanou Objednávku v souladu s podmínkami této Veřejné oferty, a to způsobem a za podmínek stanovených touto Smlouvou.</strong></p><p><strong>8.4.3. Při převzetí zkontrolovat stav obalu i samotného Zboží, zda nevykazuje vady, poškození nebo známky předchozího použití, včetně promáčklin, škrábanců a podobně. Kupující je rovněž povinen ověřit, že je Zboží kompletní a odpovídá Objednávce.</strong></p><p><strong>8.4.4. Při zadání Objednávky poskytnout Prodávajícímu úplné a pravdivé informace a osobní údaje potřebné ke zpracování a/nebo doručení Objednávky.</strong></p><p><strong>8.4.5. Plnit další povinnosti, které kupujícímu ukládá zákon Ukrajiny „O ochraně práv spotřebitelů“.</strong></p><p>9. ODPOVĚDNOST SMLUVNÍCH STRAN</p><p><strong>9.1. Smluvní strany odpovídají za nesplnění nebo nesprávné splnění podmínek této Smlouvy v souladu s touto Smlouvou a platnými právními předpisy Ukrajiny.</strong></p><p><strong>9.2. Smluvní strana, která poruší povinnost stanovenou touto Smlouvou a/nebo platnými právními předpisy Ukrajiny, nahradí druhé Smluvní straně veškerou škodu způsobenou takovým porušením, pokud byla porušena práva nebo oprávněné zájmy této Smluvní strany.</strong></p><p><strong>9.3. Nedodrží-li Kupující lhůty splatnosti ceny Zboží, může po něm Prodávající požadovat smluvní pokutu ve výši dvojnásobku diskontní sazby Národní banky Ukrajiny z dlužné částky za každý den prodlení.</strong></p><p><strong>9.4. Zaplacením smluvních pokut není Smluvní strana, která porušení zavinila, zproštěna povinnosti plnit své závazky podle této Smlouvy.</strong></p><p><strong>9.5. Prodávající je během záruční lhůty zproštěn svých záručních závazků vůči Zákazníkovi, pokud Kupující používá Zboží nesprávně a/nebo k jiným než určeným účelům, jakož i v případě mechanického, chemického či jiného poškození způsobeného Kupujícím, třetími osobami nebo okolnostmi vyšší moci.</strong></p><p><strong>9.6. Kupující nemá právo požadovat odstranění vad ani náhradu škody vzniklé v důsledku poškození nebo nepříznivých následků způsobených jeho vlastním jednáním nebo zaviněním.</strong></p><p><strong>9.7. Prodávající neodpovídá za to, že Zboží neodpovídá architektonickému stylu nemovitosti Kupujícího, na které je Zboží instalováno nebo namontováno.</strong></p><p><strong>9.8. Prodávající neodpovídá za nesprávné nebo opožděné splnění svých závazků podle této Smlouvy, pokud Kupující poskytl nepřesné nebo nepravdivé informace.</strong></p><p><strong>9.9. Prodávající neodpovídá za nesprávný provoz Zboží Kupujícím, je-li takové použití v rozporu s informacemi uvedenými v technické dokumentaci a/nebo v Návodu k obsluze, ani za jakékoli následky vyplývající z takového nesprávného provozu.</strong></p><p><strong>9.10. Smluvní strany jsou zproštěny odpovědnosti za úplné nebo částečné nesplnění svých závazků, je-li toto nesplnění důsledkem okolností vyšší moci, mezi něž patří zejména válka nebo vojenské operace, zemětřesení, povodeň, požár či jiné živelní pohromy, akty nebo jednání orgánů veřejné moci, změny celních předpisů nebo omezení dovozu a vývozu, které nastaly nezávisle na vůli Smluvních stran po uzavření této Smlouvy. Smluvní strana, která nemůže své závazky splnit, je povinna o tom druhou Smluvní stranu neprodleně informovat a předložit dokumenty vydané příslušnými orgány, které existenci takových okolností potvrzují.</strong></p><p>10. PODMÍNKY DŮVĚRNOSTI</p><p><strong>10.1. Prodávající se zavazuje nezveřejňovat osobní údaje, které Kupující poskytl při zadání Objednávky, a zajistit jejich důvěrnost a ochranu.</strong></p><p><strong>10.2. Osobními údaji mohou být zejména: identifikační údaje (příjmení, jméno a jméno po otci), adresa bydliště, poštovní směrovací číslo, kontaktní telefonní číslo, datum narození, e-mailová adresa, historie a podrobnosti nákupů na Webových stránkách a další související informace.</strong></p><p><strong>10.3. Akceptací této Oferty uděluje Kupující Prodávajícímu svolení ke shromažďování, uchovávání, zpracování a předávání osobních údajů za podmínek stanovených v této Ofertě. Souhlas se zpracováním osobních údajů platí po celou dobu trvání Smlouvy a po neomezenou dobu po jejím ukončení. Uzavřením této Smlouvy Kupující dále potvrzuje, že byl bez jakéhokoli dalšího oznámení informován o právech stanovených zákonem Ukrajiny „O ochraně osobních údajů“ a o účelech shromažďování údajů a že jeho osobní údaje jsou Prodávajícímu předávány za účelem plnění této Smlouvy, provádění vyúčtování a k dalším souvisejícím účelům. Kupující rovněž souhlasí s tím, že Prodávající je oprávněn zpřístupnit a předat osobní údaje Kupujícího třetím osobám bez jakéhokoli dalšího oznámení Kupujícímu, pokud zůstane účel zpracování osobních údajů nezměněn. Kupující si je vědom rozsahu svých práv jako subjektu osobních údajů podle zákona Ukrajiny „O ochraně osobních údajů“ a rozumí mu.</strong></p><p>11. OSTATNÍ PODMÍNKY</p><p><strong>11.1. Tato Smlouva nabývá pro Kupujícího účinnosti okamžikem zadání Objednávky prostřednictvím rozhraní Webových stránek. Smlouva zaniká splněním všech závazků, které v ní Smluvní strany sjednaly.</strong></p><p><strong>11.2. Prodávající je oprávněn zasílat Kupujícímu SMS zprávy a e-maily a uskutečňovat telefonáty za účelem informování o novinkách, akcích nebo jiných záležitostech, které nesouvisejí s konkrétní Objednávkou.</strong></p><p><strong>11.3. Prodávající je oprávněn postoupit svá práva a povinnosti z této Smlouvy na jinou osobu, aniž by k tomu potřeboval jakýkoli souhlas Kupujícího.</strong></p><p><strong>11.4. Každé ustanovení této Smlouvy je nezávislé na ostatních. Neplatnost kteréhokoli jednotlivého ustanovení této Smlouvy nezpůsobuje neplatnost Smlouvy jako celku, lze-li rozumně předpokládat, že by tato Smlouva mohla být uzavřena i bez takového ustanovení nebo podmínky.</strong></p><p><strong>11.5. Veškeré spory nebo neshody, které mohou vzniknout v souvislosti s plněním této Smlouvy, budou Smluvní strany řešit jednáním. Nedojde-li k dohodě, budou takové spory a neshody řešeny soudní cestou v souladu s platnými právními předpisy Ukrajiny.</strong></p><p><strong>11.6. Ve věcech, které tato Smlouva neupravuje, se Smluvní strany řídí platnými právními předpisy Ukrajiny.</strong></p><p><strong>11.7. Dojde-li ke změně údajů Smluvní strany, včetně osobních údajů, adres, bankovního spojení nebo jiných informací, je Smluvní strana, které se změna týká, povinna o ní druhou Smluvní stranu informovat do dvou pracovních dnů.</strong></p><p>PRODÁVAJÍCÍ:</p><h3>Společnost s ručením omezeným „UA Green“</h3><h3>Kód EDRPOU: 45033277</h3><h3>Adresa: ulice Sadova 1, byt 117, obec Chroly, Charkovská oblast</h3><h3>E-mail: moc.neergau%40olleh</h3><h3>Telefon: +38 (095) 717 37 72</h3>$c$, now()) ON CONFLICT (key, lang) DO NOTHING;
