UPDATE products SET name_cs = COALESCE(name_cs, $c$Audit větru na pozemku$c$), short_desc_cs = COALESCE(short_desc_cs, $c$Zjistěte během jediného dne, zda se vám vyplatí instalovat větrnou elektrárnu právě na vašem pozemku.$c$), description_html_cs = COALESCE(description_html_cs, $c$<p>Zjistěte během jediného dne, zda se vám vyplatí instalovat větrnou elektrárnu právě na vašem pozemku.</p><p>Náš specialista navštíví místo budoucí instalace, analyzuje lokalitu a připraví zprávu s předběžným posouzením větrného potenciálu, doporučeným místem instalace a typem turbíny. Podložené rozhodnutí tak získáte ještě před většími investicemi.</p><p>Co služba zahrnuje:</p><p>Analýzu modelových dat o větru podle souřadnic vašeho pozemku (průměrná roční rychlost větru, větrná růžice a rozložení podle výšky)</p><p>Výjezd specialisty a prohlídku pozemku: terén, překážky, drsnost povrchu a zdroje turbulence</p><p>Orientační měření větru na místě jako referenční bod</p><p>Posouzení příjezdových cest a podmínek pro dopravu a montáž zařízení</p><p>Určení nejbližšího místa připojení k distribuční síti</p><p>Ověření vzdálenosti od obytné zástavby (hluk, stroboskopický efekt stínů)</p><p>Výběr optimálního místa instalace a doporučeného typu a výšky turbíny</p><p>Co získáte:</p><p>Písemnou zprávu s předběžnou prognózou roční výroby energie, doporučeními k umístění a typu turbíny a přehledem zjištěných omezení.</p><p>Pro koho je služba určena:</p><p>Pro vlastníky pozemků, farmy, domácnosti a firmy, které zvažují větrnou energii a chtějí si před zahájením projektu ověřit jeho proveditelnost.</p>$c$), seo_title_cs = COALESCE(seo_title_cs, $c$Audit větru na vašem pozemku$c$), seo_desc_cs = COALESCE(seo_desc_cs, $c$Zjistěte během jediného dne, zda se vám vyplatí instalovat větrnou elektrárnu právě na vašem pozemku.
Náš specialista navštíví místo instalace, analyzuje lokalitu a připraví zprávu s předběžným posouzením větrného potenciálu, doporučeným místem instalace a typem turbíny.$c$) WHERE slug = $c$audit-vitrovih-resursiv$c$;
UPDATE products SET name_cs = COALESCE(name_cs, $c$Větrná elektrárna 5 kW$c$), short_desc_cs = COALESCE(short_desc_cs, $c$Výkonná vertikální větrná elektrárna 5 kW!$c$), description_html_cs = COALESCE(description_html_cs, $c$<p>Výkonná vertikální větrná elektrárna 5 kW!</p><p>📌Standardní sada obsahuje:</p><ul><li>větrná turbína 5 kW, 48 V</li><li>regulátor nabíjení 5 kW</li><li>50 m kabelu</li><li>balastní zátěž 5 kW</li></ul><h3>Generátor</h3><p>Typ: třífázový synchronní PMG</p><p>Generátor s permanentními magnety NdFeB</p><p>Jmenovitý výkon: 5 kW</p><p>Maximální výkon: 6,5 kW</p><p>Jmenovité napětí: 48 V</p><p>Hmotnost generátoru: 210 kg</p><h3>Rotor</h3><p>Průměr rotoru: 5 metrů</p><p>Délka lopatky: 4,75 metru</p><p>Plocha rotoru: 22 m²</p><p>Počet lopatek: 3 ks</p><p>Materiál lopatek: sklolaminát (kompozit)</p><h3>Rozsah rychlostí větru</h3><p>Rozběhová rychlost: 1,5 m/s</p><p>Jmenovitá rychlost: 12 m/s</p><p>Provozní rozsah: 2–25 m/s</p><p>Odolá větru až do: 45 m/s</p><p>Jmenovité otáčky: 250 ot./min</p><h3>Ochrana</h3><p>Stupeň krytí: IP54</p><p>Teplotní rozsah: -40 až +60 °C</p><p>Ochrana proti větru: brzdění pomocí balastní zátěže</p><p>Vertikální elektrárny jsou sice méně výkonné než horizontální, přesto však mají řadu výhod.</p><p>Dlouhá životnost</p><p>Jednodušší konstrukce znamená méně pohyblivých dílů, které je třeba udržovat a které se mohou porouchat.</p><p>Tichý provoz</p><p>Vertikální větrné elektrárny jsou tišší než horizontální, protože se otáčejí pomaleji. Hladina hluku nepřesahuje 38 dB. Nižší otáčky sice snižují účinnost, ale díky nim je elektrárna vhodnější pro instalaci na vícepodlažních budovách i v soukromých domácnostech.</p><p>Nižší vibrace a šetrnost k přírodě</p><p>Vysoké otáčky horizontálních elektráren způsobují silnější vibrace, které se přenášejí na stožár. Je-li stožár zabetonován uprostřed zahrady nebo pole, klesá úrodnost půdy, protože hmyz a žížaly, které ji obohacují, vylézají na povrch v domnění, že prší, a stávají se snadnou kořistí ptáků.</p><p>Estetika</p><p>Vertikální větrná elektrárna působí za provozu futuristicky a zajímavě.</p><p>Zóny instalace:</p><p>Zóna 1 – Lvovská oblast</p><p>Zóna 2 – Volyňská oblast, Ternopilská oblast, Rivnenská oblast, Ivanofrankivská oblast.</p><p>Zóna 3 – Vinnycká oblast, Žytomyrská oblast, Zakarpatská oblast, Kyjevská oblast, Chmelnycká oblast, Čerkaská oblast, Černovická oblast, Černihivská oblast.</p><p>Zóna 4 – Charkovská oblast, Dněpropetrovská oblast, Chersonská oblast, Mykolajivská oblast, Kirovohradská oblast, Oděská oblast, Sumská oblast, Poltavská oblast.</p>$c$), specs_html_cs = COALESCE(specs_html_cs, $c$<table><tr><th>Jmenovitý výkon</th><td>5 kW</td></tr><tr><th>Špičkový výkon</th><td>6,5 kW</td></tr><tr><th>Provozní napětí</th><td>48 V</td></tr><tr><th>Hladina hluku</th><td>38 dB</td></tr><tr><th>Vinutí generátoru</th><td>Měď 1,6 mm (Galkat)</td></tr><tr><th>Materiál statoru</th><td>Elektrotechnická ocel</td></tr><tr><th>Materiál lopatek</th><td>Epoxidový kompozit se skelnou tkaninou</td></tr><tr><th>Hmotnost</th><td>300 kg</td></tr><tr><th>Průměr</th><td>4,75 m</td></tr><tr><th>Výška</th><td>4,75 m</td></tr><tr><th>Typ regulátoru</th><td>MPPT</td></tr><tr><th>Země původu</th><td>Ukrajina</td></tr><tr><th>Značka</th><td>UA Green</td></tr></table>$c$), faq_html_cs = COALESCE(faq_html_cs, $c$<h3>1. Kolik elektřiny větrná elektrárna 5 kW skutečně vyrobí?</h3><p>Průměrná roční výroba větrné elektrárny K5 je 1,3 kW za hodinu. V zimě dosáhnete lepších výsledků – v průměru zhruba o 30 % lepších než v létě.</p><h3>2. Proč je vertikální elektrárna pro dům lepší než horizontální?</h3><p>Vertikální větrná elektrárna je konstruována pro tichý chod rotoru, díky čemuž je téměř neslyšná – na rozdíl od horizontálních elektráren, které vydávají neustálé pískání a hučení.</p><p>Důležitým faktorem jsou také vibrace: horizontální elektrárny přenášejí vibrace na stožár a ten dále do půdy, což vede k úbytku půdní fauny a snižuje úrodnost půdy v okolí takové elektrárny.</p><p>A samozřejmě ekologický faktor. Rychlé a tenké lopatky horizontální elektrárny jsou pro ptáky téměř neviditelné a mohou je zranit nebo usmrtit.</p><h3>3. Jak často je potřeba servis?</h3><p>Jako každé zařízení vyžaduje i elektrárna pravidelnou údržbu. V průměru je servis potřeba jednou ročně nebo po každých 12–15 tisících vyrobených kilowattů. Společnost UA Green zajišťuje kompletní servis elektráren po celé Ukrajině a rychlé dodání všech komponentů. Pracujeme také na nástrojích využívajících umělou inteligenci, které umožní optimálnější servis našich elektráren a předcházení kritickým poruchám.</p><h3>4. Jaká je doba návratnosti elektrárny?</h3><p>Návratnost se u firem a domácností na Ukrajině výrazně liší kvůli rozdílným tarifům za elektřinu. Firmám se investice v průměru vrátí za 1 až 2 roky, domácnostem zhruba za 5–6 let.</p>$c$), seo_title_cs = COALESCE(seo_title_cs, $c$Větrná elektrárna 5 kW$c$), seo_desc_cs = COALESCE(seo_desc_cs, $c$Vertikální větrné elektrárny K5 nabízejí řadu výhod: dlouhou životnost, tichý provoz, nižší vibrace, šetrnost k životnímu prostředí a estetický vzhled.$c$) WHERE slug = $c$k5v1$c$;
